<?php
declare(strict_types=1);
namespace App\EventSubscriber;
use App\Cms\CmsSlug; use App\Entity\Cms\{CmsPage,CmsPageTranslation}; use Doctrine\Bundle\DoctrineBundle\Attribute\AsDoctrineListener; use Doctrine\ORM\Event\OnFlushEventArgs; use Doctrine\ORM\Events;
#[AsDoctrineListener(event:Events::onFlush)] final class CmsSlugRedirectSubscriber { public function onFlush(OnFlushEventArgs $event):void { $em=$event->getObjectManager();$uow=$em->getUnitOfWork();foreach($uow->getScheduledEntityUpdates() as $entity){if(!$entity instanceof CmsPageTranslation||!$entity->getPage() instanceof CmsPage||$entity->getPage()->getStatus()!==CmsPage::STATUS_PUBLISHED)continue;$change=$uow->getEntityChangeSet($entity)['slug']??null;if(!is_array($change))continue;$old=CmsSlug::normalize((string)$change[0]);$new=CmsSlug::normalize((string)$change[1]);if($old===''||$old===$new)continue;foreach($entity->getPage()->getChannels() as $channel){$em->getConnection()->executeStatement('INSERT IGNORE INTO cardnext_cms_redirect (channel_id,target_page_id,locale,source_path,target_path,status_code,created_at) VALUES (:channel,:page,:locale,:source,:target,301,NOW())',['channel'=>$channel->getId(),'page'=>$entity->getPage()->getId(),'locale'=>$entity->getLocale(),'source'=>$old,'target'=>$new]);}} } }
